const resource = $input.first().json.resources || $input.first().json;
const resourceId = Array.isArray(resource) ? resource[0].id : resource.id;
return [{ json: { resourceId } }];

const resource = $input.first().json;
const users = $input.last().json.users || [];

const notifications = users.map(user => ({
  user_id: user.id,
  user_email: user.email,
  user_name: user.full_name,
  resource_id: resource.id,
  resource_title: resource.title,
  resource_category: resource.category,
  resource_type: resource.resource_type,
  resource_url: resource.external_url || `/resources/${resource.id}`,
  author_name: resource.author_name
}));

return [{ json: { notifications, count: notifications.length } }];

